import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class GreedyTour {
    // Greedy change: always take the largest coin that still fits
    static List<Integer> greedyChange(int[] coinsDesc, int amount) {
        List<Integer> used = new ArrayList<>();
        for (int coin : coinsDesc) {
            while (amount >= coin) {
                used.add(coin);
                amount -= coin;
            }
        }
        return used;
    }

    public static void main(String[] args) {
        System.out.println("US coins, 68 cents: " + greedyChange(new int[]{25, 10, 5, 1}, 68));
        System.out.println("coins {4, 3, 1}, 6:  " + greedyChange(new int[]{4, 3, 1}, 6) + " but [3, 3] uses fewer coins");

        // Interval scheduling: earliest finish first
        int[][] talks = {{9, 12}, {10, 11}, {11, 13}, {12, 14}, {13, 15}, {9, 10}};
        int[][] byFinish = talks.clone();
        Arrays.sort(byFinish, (a, b) -> Integer.compare(a[1], b[1]));
        int lastEnd = Integer.MIN_VALUE;
        List<String> chosen = new ArrayList<>();
        for (int[] t : byFinish) {
            if (t[0] >= lastEnd) {                 // starts after the previous chosen talk ends
                chosen.add(t[0] + "-" + t[1]);
                lastEnd = t[1];
            }
        }
        System.out.println("most talks one person can attend: " + chosen);
    }
}

import java.util.Arrays;

public class GreedyChoice {
    static int greedyCount(int[] coinsDesc, int amount) {
        int count = 0;
        for (int c : coinsDesc) { count += amount / c; amount %= c; }
        return count;
    }

    static int optimalCount(int[] coins, int amount) {     // small DP, used as the referee
        int[] best = new int[amount + 1];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (int c : coins)
                if (c <= a && best[a - c] != Integer.MAX_VALUE) best[a] = Math.min(best[a], best[a - c] + 1);
        return best[amount];
    }

    public static void main(String[] args) {
        int[][] systems = {{25, 10, 5, 1}, {4, 3, 1}};
        for (int[] coins : systems) {
            StringBuilder losses = new StringBuilder();
            for (int amount = 1; amount <= 30; amount++) {
                int g = greedyCount(coins, amount), o = optimalCount(coins, amount);
                if (g != o) losses.append(amount).append(" (").append(g).append(" vs ").append(o).append(") ");
            }
            System.out.println("coins " + Arrays.toString(coins) + ": greedy loses at "
                    + (losses.length() == 0 ? "no amount up to 30" : losses.toString().trim()));
        }

        // Fractional knapsack: best value per kilo first
        String[] names = {"gold dust", "silver", "spices", "tea"};
        int[] value = {600, 300, 120, 100};
        int[] weight = {10, 15, 6, 10};
        Integer[] order = {0, 1, 2, 3};
        Arrays.sort(order, (a, b) -> Double.compare((double) value[b] / weight[b], (double) value[a] / weight[a]));
        double capacity = 20, total = 0;
        for (int i : order) {
            if (capacity == 0) break;
            double take = Math.min(weight[i], capacity);
            capacity -= take;
            total += take * value[i] / weight[i];
            System.out.printf("take %4.1f kg of %-9s (%.1f per kg)%n", take, names[i], (double) value[i] / weight[i]);
        }
        System.out.printf("fractional knapsack value for 20 kg: %.1f%n", total);
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class ActivitySelection {
    // Sort by the rule, then take every activity that starts after the last one taken ends
    static List<String> select(int[][] acts, Comparator<int[]> rule, boolean trace) {
        int[][] sorted = acts.clone();
        Arrays.sort(sorted, rule);
        List<String> taken = new ArrayList<>();
        int lastEnd = Integer.MIN_VALUE;
        for (int[] a : sorted) {
            String label = "[" + a[0] + "," + a[1] + ")";
            if (a[0] >= lastEnd) {                 // >=: may start exactly when the last one ends
                taken.add(label);
                lastEnd = a[1];
                if (trace) System.out.println("  take " + label);
            } else if (trace) {
                System.out.println("  skip " + label + ": starts before " + lastEnd);
            }
        }
        return taken;
    }

    public static void main(String[] args) {
        Comparator<int[]> byFinish = Comparator.comparingInt(a -> a[1]);
        Comparator<int[]> byStart = Comparator.comparingInt(a -> a[0]);
        Comparator<int[]> byLength = Comparator.comparingInt(a -> a[1] - a[0]);

        int[][] meetings = {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {3, 9}, {5, 9}, {6, 10}, {8, 11}, {8, 12}, {2, 14}, {12, 16}};
        System.out.println("earliest finish first:");
        System.out.println("  -> " + select(meetings, byFinish, true).size() + " meetings");

        int[][] longFirst = {{0, 10}, {1, 2}, {3, 4}, {5, 6}};
        System.out.println("earliest start on " + show(longFirst) + ": " + select(longFirst, byStart, false)
                + " vs finish rule " + select(longFirst, byFinish, false));
        int[][] shortMiddle = {{0, 5}, {4, 7}, {6, 11}};
        System.out.println("shortest first on " + show(shortMiddle) + ": " + select(shortMiddle, byLength, false)
                + " vs finish rule " + select(shortMiddle, byFinish, false));
    }

    static String show(int[][] acts) {
        StringBuilder sb = new StringBuilder();
        for (int[] a : acts) sb.append("[").append(a[0]).append(",").append(a[1]).append(")");
        return sb.toString();
    }
}

