def select(acts, rule, trace):
    """Sort by the rule, then take every activity that starts after the last one taken ends."""
    taken, last_end = [], float("-inf")
    for start, end in sorted(acts, key=rule):
        label = f"[{start},{end})"
        if start >= last_end:  # >=: may start exactly when the last one ends
            taken.append(label)
            last_end = end
            if trace:
                print("  take", label)
        elif trace:
            print(f"  skip {label}: starts before {last_end}")
    return taken


def by_finish(a):
    return a[1]


def by_start(a):
    return a[0]


def by_length(a):
    return a[1] - a[0]


def show(acts):
    return "".join(f"[{s},{e})" for s, e in acts)


def listed(items):
    return "[" + ", ".join(items) + "]"


