import java.util.Map;
import java.util.PriorityQueue;
import java.util.TreeMap;

public class HuffmanCoding {
    static class Node {
        final int freq, seq;
        final char ch;                 // '\0' for internal nodes
        final Node left, right;
        Node(int freq, int seq, char ch, Node left, Node right) {
            this.freq = freq; this.seq = seq; this.ch = ch; this.left = left; this.right = right;
        }
        String label() { return ch != '\0' ? "'" + ch + "'" : "(" + freq + ")"; }
    }

    static void assign(Node n, String code, Map<Character, String> codes) {
        if (n.left == null) {          // a leaf
            codes.put(n.ch, code.isEmpty() ? "0" : code);
            return;
        }
        assign(n.left, code + "0", codes);
        assign(n.right, code + "1", codes);
    }

    public static void main(String[] args) {
        String text = "abracadabra alakazam";
        Map<Character, Integer> freq = new TreeMap<>();
        for (char c : text.toCharArray()) freq.merge(c, 1, Integer::sum);
        System.out.println("frequencies: " + freq);

        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> a.freq != b.freq ? Integer.compare(a.freq, b.freq) : Integer.compare(a.seq, b.seq));
        int seq = 0;
        for (Map.Entry<Character, Integer> e : freq.entrySet()) pq.add(new Node(e.getValue(), seq++, e.getKey(), null, null));
        while (pq.size() > 1) {
            Node a = pq.poll(), b = pq.poll();                  // the two rarest
            Node parent = new Node(a.freq + b.freq, seq++, '\0', a, b);
            System.out.println("  merge " + a.label() + "=" + a.freq + " + " + b.label() + "=" + b.freq + " -> " + parent.freq);
            pq.add(parent);
        }
        Map<Character, String> codes = new TreeMap<>();
        assign(pq.poll(), "", codes);

        int bits = 0;
        for (Map.Entry<Character, String> e : codes.entrySet()) {
            System.out.println("  '" + e.getKey() + "' x" + freq.get(e.getKey()) + " -> " + e.getValue());
            bits += freq.get(e.getKey()) * e.getValue().length();
        }
        int fixedBits = 32 - Integer.numberOfLeadingZeros(freq.size() - 1);   // bits per symbol, fixed length
        System.out.println("Huffman: " + bits + " bits; fixed " + fixedBits + "-bit code: " + fixedBits * text.length()
                + " bits; 8-bit ASCII: " + 8 * text.length() + " bits");
    }
}

public class GreedyMst {
    static final int INF = Integer.MAX_VALUE;

    public static void main(String[] args) {
        String names = "ABCDE";
        int[][] w = {                  // dense: every pair of sites has a cable cost
            {0, 4, 2, 7, 9},
            {4, 0, 5, 3, 6},
            {2, 5, 0, 8, 4},
            {7, 3, 8, 0, 5},
            {9, 6, 4, 5, 0},
        };
        int n = w.length;

        // Cut property on {A, B} vs {C, D, E}
        int bestU = -1, bestV = -1;
        StringBuilder crossing = new StringBuilder();
        for (int u : new int[]{0, 1})
            for (int v : new int[]{2, 3, 4}) {
                crossing.append(names.charAt(u)).append('-').append(names.charAt(v)).append('=').append(w[u][v]).append(' ');
                if (bestU == -1 || w[u][v] < w[bestU][bestV]) { bestU = u; bestV = v; }
            }
        System.out.println("edges crossing {A,B} | {C,D,E}: " + crossing.toString().trim());
        System.out.println("lightest crossing edge: " + names.charAt(bestU) + "-" + names.charAt(bestV));

        // Prim, O(V^2) array version
        int[] best = new int[n], from = new int[n];
        boolean[] inTree = new boolean[n];
        java.util.Arrays.fill(best, INF);
        best[0] = 0;
        from[0] = -1;
        int total = 0;
        for (int round = 0; round < n; round++) {
            int u = -1;
            for (int v = 0; v < n; v++) if (!inTree[v] && (u == -1 || best[v] < best[u])) u = v;   // O(V) scan
            inTree[u] = true;
            total += best[u];
            if (from[u] >= 0) System.out.println("add " + names.charAt(from[u]) + "-" + names.charAt(u) + " (" + best[u] + ")");
            for (int v = 0; v < n; v++) {
                if (!inTree[v] && w[u][v] < best[v]) { best[v] = w[u][v]; from[v] = u; }
            }
        }
        System.out.println("MST total " + total + "; direct edge B-E costs " + w[1][4] + ", the tree route B-A-C-E costs " + (w[1][0] + w[0][2] + w[2][4]));
    }
}
